def inr_format(amount):
    # Convert to string to handle digit grouping
    amount_str = str(amount)

    # Split into groups of 3 and 2 digits
    groups = [
        amount_str[-3:] if len(amount_str) > 3 else amount_str,
        amount_str[-2:] if len(amount_str) > 2 else amount_str
    ]

    # Join with commas
    return ','.join(groups)

